#!/usr/bin/env bash
set -Eeuo pipefail
PAYLOAD_SHA256="7568035dd255fe21b2abd8b924474f483b4a230cc612ecd061f8e30831f57e57"
PAYLOAD_BYTES="1837734"
MARKER="__VELORAOS_1160_CURRENT_PAYLOAD__"
TMPDIR="$(mktemp -d /tmp/veloraos-1.16.0-current.XXXXXX)"
cleanup(){ rm -rf "$TMPDIR"; }
trap cleanup EXIT INT TERM
[[ ${EUID:-$(id -u)} -eq 0 ]] || { echo 'Run this script with sudo.' >&2; exit 1; }
for command in awk base64 tr sha256sum stat tar; do command -v "$command" >/dev/null 2>&1 || { echo "Required command is missing: $command" >&2; exit 1; }; done
PAYLOAD_FILE="$TMPDIR/payload.tar.gz"
awk -v marker="$MARKER" '{line=$0; sub(/\r$/, "", line)} line==marker{found=1;next}found{print}END{if(!found)exit 2}' "$0" | tr -d '[:space:]' | base64 --decode > "$PAYLOAD_FILE" || { echo 'Installer payload is missing or invalid.' >&2; exit 1; }
[[ "$(stat -c '%s' "$PAYLOAD_FILE")" == "$PAYLOAD_BYTES" ]] || { echo 'Installer payload size check failed.' >&2; exit 1; }
ACTUAL_PAYLOAD_SHA256="$(sha256sum "$PAYLOAD_FILE" | awk '{print $1}')"
[[ "$ACTUAL_PAYLOAD_SHA256" == "$PAYLOAD_SHA256" ]] || { echo 'Installer payload integrity check failed.' >&2; exit 1; }
tar -tzf "$PAYLOAD_FILE" >/dev/null || { echo 'Installer payload archive validation failed.' >&2; exit 1; }
tar -xzf "$PAYLOAD_FILE" -C "$TMPDIR"
chmod 0755 "$TMPDIR/veloraos-1.16.0/installer/veloraos-install.sh"
exec /bin/bash "$TMPDIR/veloraos-1.16.0/installer/veloraos-install.sh" "$@"
